def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int | None:
        if token.isdigit():
            return int(token)
        return None

    for i, op in enumerate(ops):
        tokens = op.split(" ")
        if not tokens or not tokens[0]:
            rejected.append(i)
            continue

        cmd = tokens[0]

        if cmd == "open":
            if len(tokens) != 3:
                rejected.append(i)
                continue
            a, n_str = tokens[1], tokens[2]
            n = parse_amount(n_str)
            if n is None or n < 0 or a in balances:
                rejected.append(i)
                continue
            balances[a] = n
            history.append(("open", a))

        elif cmd == "deposit":
            if len(tokens) != 3:
                rejected.append(i)
                continue
            a, n_str = tokens[1], tokens[2]
            n = parse_amount(n_str)
            if n is None or n <= 0 or a not in balances:
                rejected.append(i)
                continue
            balances[a] += n
            history.append(("deposit", a, n))

        elif cmd == "withdraw":
            if len(tokens) != 3:
                rejected.append(i)
                continue
            a, n_str = tokens[1], tokens[2]
            n = parse_amount(n_str)
            if (
                n is None
                or n <= 0
                or a not in balances
                or a in frozen
                or balances[a] < n
            ):
                rejected.append(i)
                continue
            balances[a] -= n
            history.append(("withdraw", a, n))

        elif cmd == "transfer":
            if len(tokens) != 4:
                rejected.append(i)
                continue
            a, b, n_str = tokens[1], tokens[2], tokens[3]
            n = parse_amount(n_str)
            if (
                n is None
                or n <= 0
                or a == b
                or a not in balances
                or b not in balances
                or a in frozen
                or balances[a] < n
            ):
                rejected.append(i)
                continue
            balances[a] -= n
            balances[b] += n
            history.append(("transfer", a, b, n))

        elif cmd == "freeze":
            if len(tokens) != 2:
                rejected.append(i)
                continue
            a = tokens[1]
            if a not in balances or a in frozen:
                rejected.append(i)
                continue
            frozen.add(a)
            history.append(("freeze", a))

        elif cmd == "unfreeze":
            if len(tokens) != 2:
                rejected.append(i)
                continue
            a = tokens[1]
            if a not in balances or a not in frozen:
                rejected.append(i)
                continue
            frozen.remove(a)
            history.append(("unfreeze", a))

        elif cmd == "undo":
            if len(tokens) != 1 or not history:
                rejected.append(i)
                continue
            last_op = history.pop()
            op_type = last_op[0]
            if op_type == "open":
                del balances[last_op[1]]
                frozen.discard(last_op[1])
            elif op_type == "deposit":
                balances[last_op[1]] -= last_op[2]
            elif op_type == "withdraw":
                balances[last_op[1]] += last_op[2]
            elif op_type == "transfer":
                balances[last_op[1]] += last_op[3]
                balances[last_op[2]] -= last_op[3]
            elif op_type == "freeze":
                frozen.remove(last_op[1])
            elif op_type == "unfreeze":
                frozen.add(last_op[1])

        else:
            rejected.append(i)

    return balances, rejected
